        -- 001_create_tick_schema.sql
        -- AlphaWave-7 tick data schema migration
        -- Migrates from legacy CSV to Parquet + relational schema

        CREATE TABLE IF NOT EXISTS tick_data (
            trade_date DATE NOT NULL,
            symbol VARCHAR(10) NOT NULL,
            open DECIMAL(12,4),
            high DECIMAL(12,4),
            low DECIMAL(12,4),
            close DECIMAL(12,4),
            volume BIGINT,
            PRIMARY KEY (trade_date, symbol)
        );

        CREATE TABLE IF NOT EXISTS universe_constituents (
            as_of_date DATE NOT NULL,
            symbol VARCHAR(10) NOT NULL,
            company_name VARCHAR(200),
            sector VARCHAR(100),
            listing_status VARCHAR(20) DEFAULT 'ACTIVE',
            is_pit_corrected BOOLEAN DEFAULT FALSE,
            PRIMARY KEY (as_of_date, symbol)
        );

        -- Backtest period: 2018-01-01 to 2022-12-31
